import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.vLhlLNVn.js";const y=JSON.parse('{"title":"Periods, updates and time","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/05.hintergrund/03.perioden-und-zeit.md"},"headers":[],"relativePath":"adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","filePath":"adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/hintergrund/perioden-und-zeit.md"};function s(i,e,d,h,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="periods-updates-and-time" tabindex="-1">Periods, updates and time <a class="header-anchor" href="#periods-updates-and-time" aria-label="Permalink to &quot;Periods, updates and time&quot;">​</a></h1><p><a id="values-updated-live-midnight"></a></p><h2 id="when-are-values-updated-live-or-at-midnight" tabindex="-1">When are values updated: live or at midnight? <a class="header-anchor" href="#when-are-values-updated-live-or-at-midnight" aria-label="Permalink to &quot;When are values updated: live or at midnight?&quot;">​</a></h2><p>Both. SourceAnalytix recalculates the running values immediately with every new value from the source. At midnight it also writes the previous periods such as &quot;yesterday&quot; and starts the new periods at 0.</p><table tabindex="0"><thead><tr><th>Values</th><th>When</th></tr></thead><tbody><tr><td>total and running periods (day to year, weekdays, weeks, months, quarters)</td><td>with every new value from the source, if it changes</td></tr><tr><td>previous periods (yesterday, last week …)</td><td>at the period rollover, timestamped 23:59:59 on the last day</td></tr><tr><td>start values in the source settings</td><td>at the period rollover</td></tr></tbody></table><p>If the source sends nothing for a while, the SourceAnalytix values stand still too.</p><p>At 0:00, the day always ends, the week on Mondays, the month on the 1st, the quarter on 1 January, April, July and October, and the year on 1 January. Values that arrive during the rollover are buffered and then processed in order.</p><p>If ioBroker was off at midnight, SourceAnalytix catches up the rollover on start, see <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker was off at midnight</a>.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Where do I find yesterday, last week, last month?</a> · <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Crash or rollover at the wrong time</a></p><p><a id="week-52-53-have-values"></a></p><h2 id="why-does-week-52-53-show-values-in-the-new-year" tabindex="-1">Why does week 52/53 show values in the new year? <a class="header-anchor" href="#why-does-week-52-53-show-values-in-the-new-year" aria-label="Permalink to &quot;Why does week 52/53 show values in the new year?&quot;">​</a></h2><p>Because SourceAnalytix counts calendar weeks according to ISO 8601: the week starts on Monday, and week 1 is the week with the year&#39;s first Thursday. Early January can therefore still be week 52 or 53 of the previous year.</p><table tabindex="0"><thead><tr><th>Days</th><th>Calendar week</th></tr></thead><tbody><tr><td>29 Dec 2025 to 4 Jan 2026</td><td>week 1 of 2026</td></tr><tr><td>28 Dec 2026 to 3 Jan 2027</td><td>week 53 of 2026</td></tr></tbody></table><ul><li>&quot;Current week&quot; always counts the whole week, even across the turn of the year. &quot;Current year&quot; starts at 0 on 1 January.</li><li>The weeks under <code>currentYear</code> only show weeks of the current year.</li><li>In the year archive, each week is in the folder of its ISO year, so week 53 of 2026 is under <code>2026</code>, including the January days.</li></ul><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#happens-turn-year">What happens at the turn of the year?</a></p><p><a id="sourceanalytix-calculate-retroactively-only-activation"></a></p><h2 id="does-sourceanalytix-calculate-retroactively-or-only-from-activation" tabindex="-1">Does SourceAnalytix calculate retroactively or only from activation? <a class="header-anchor" href="#does-sourceanalytix-calculate-retroactively-or-only-from-activation" aria-label="Permalink to &quot;Does SourceAnalytix calculate retroactively or only from activation?&quot;">​</a></h2><p>From activation. If you know the meter readings at the start of the running periods, enter them as start values, and the consumption since the start of the period is included.</p><p>The &quot;Add source&quot; wizard asks for this in the &quot;Start values&quot; step:</p><table tabindex="0"><thead><tr><th>Choice</th><th>What happens</th></tr></thead><tbody><tr><td>&quot;Count from now&quot;</td><td>All periods start at 0 now.</td></tr><tr><td>&quot;Include consumption since the start of the period&quot;</td><td>You enter the meter readings at the start of day, week, month, quarter and year. Empty fields count from now.</td></tr></tbody></table><p>SourceAnalytix cannot create earlier periods such as last year, and the previous periods only fill after the first rollover. Power sources (W) always count from activation, because they don&#39;t deliver a meter reading.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values?</a></p><p><a id="week-month-quarter-year-values"></a></p><h2 id="why-do-week-month-quarter-and-year-values-differ" tabindex="-1">Why do week, month, quarter and year values differ? <a class="header-anchor" href="#why-do-week-month-quarter-and-year-values-differ" aria-label="Permalink to &quot;Why do week, month, quarter and year values differ?&quot;">​</a></h2><p>Because each period starts at a different time and has its own start value. Consumption is always the total minus that period&#39;s start value.</p><p>Typical reasons:</p><ul><li><strong>A week across the month boundary:</strong> on Saturday, 3 Oct 2026, the month counts three days and the week five, because it began on Monday, 28 Sep.</li><li><strong>Activation in the middle of a period:</strong> without start values, month, quarter and year contain the same amount at first.</li><li><strong>Rounding:</strong> each period value is rounded on its own. The sum of the days can differ in the last digit.</li><li><strong>Basic fee:</strong> it is booked monthly, not spread over the days, see <a href="./../anleitungen/preise-und-kosten#include-monthly-base-fee">Basic fee</a>.</li></ul><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">Which states are there for weeks, months and weekdays?</a></p>',28)])])}const p=t(n,[["render",s]]);export{y as __pageData,p as default};
